function normalizeWorkflowTasks(){tasks.forEach(t=>{t.collaborators??=[];t.requests??=[];t.submissions??=[];t.approvals??=[];t.revision??=0;t.assignmentHistory??=[];if(t.assignedBy===undefined){t.assignedBy=['director','supervisor'].includes(members[t.creator]?.access)?t.creator:members.findIndex(m=>m.active&&m.access==='director')}if(t.status==='انجام‌شده'){t.legacyCompletedAt=t.completed;t.status=t.sample?'بسته‌شده':'آماده بررسی';t.completed=t.sample?t.completed:null}if(!taskStates.includes(t.status))t.status='تعریف‌شده';if(t.status==='آماده بررسی'&&!t.reviewSubmission){t.status='در حال انجام';t.progress=95}});}
