const workflowDB=new Promise((resolve,reject)=>{const r=indexedDB.open('samandis-automation-v1',2);r.onupgradeneeded=()=>{for(const [name,key]of [['letters','id'],['files','id'],['meta','id'],['versions','id']])if(!r.result.objectStoreNames.contains(name)){const s=r.result.createObjectStore(name,{keyPath:key});if(name==='versions')s.createIndex('taskId','taskId')}};r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);r.onblocked=()=>toast('برای فعال‌شدن ذخیره فایل‌ها، تب قدیمی نمونه را ببندید.')});workflowDB.catch(()=>{});
