function openNotices(){const list=notices.filter(n=>n.recipient===me());$('#noticeBody').innerHTML=`<div class="dialog-head"><h2>اعلان‌های شما</h2><button class="close" id="closeNotices">×</button></div><p class="hint">اعلان بازخورد، ارجاع و بررسی کارها در نمونه همین مرورگر ثبت می‌شود. اعلان گوشی هنگام بسته‌بودن سایت، پس از اتصال نسخه مشترک فعال خواهد شد.</p>${list.length?'<button id="readAll" class="text-btn">همه را خواندم</button>':''}<div>${list.map(n=>`<button class="notice-item ${n.read?'':'unread'}" data-notice="${n.id}"><span>${esc(n.text)}</span><small>${esc(people[n.actor])} · ${fmt(n.created)}</small></button>`).join('')||empty('اعلان تازه‌ای ندارید.')}</div>`;$('#noticePanel').showModal();$('#closeNotices').onclick=()=>$('#noticePanel').close();if($('#readAll'))$('#readAll').onclick=()=>{notices.forEach(n=>{if(n.recipient===me())n.read=true});localStorage.setItem('daraei-notices-v1',JSON.stringify(notices));renderBell();$('#noticePanel').close();openNotices()};$('#noticeBody').querySelectorAll('[data-notice]').forEach(b=>b.onclick=()=>{const n=notices.find(n=>n.id===b.dataset.notice&&n.recipient===me());if(!n)return;n.read=true;localStorage.setItem('daraei-notices-v1',JSON.stringify(notices));renderBell();$('#noticePanel').close();detail(n.taskId)})}
