function submitReview(t,versionId,versions){if(!canSubmitTask(t))throw Error('ارسال برای بررسی مجاز نیست');if(!members[t.assignedBy]?.active||!['director','supervisor'].includes(members[t.assignedBy]?.access))throw Error('ابتدا بررسی‌کننده فعال تعیین شود');const v=versions.find(v=>v.id===versionId);if(versions.length&&!v)throw Error('نسخه تحویل را انتخاب کنید');if(v&&v.taskId!==t.id)throw Error('نسخه متعلق به این کار نیست');const submission={id:crypto.randomUUID(),at:now(),by:me(),versionId:v?.id||null,revision:t.revision,description:t.description};t.reviewSubmission=submission;t.submissions.push(submission);t.status='آماده بررسی';t.progress=100;stateLog(t,'برای تأیید نهایی به '+people[t.assignedBy]+' ارسال شد.');notifyTask(t,[t.assignedBy],'«'+t.title+'» آماده بررسی و تأیید نهایی است.');save()}
