async function addTaskVersion(t,files,label){if(!canContribute(t)||t.status==='بسته‌شده')throw Error('افزودن فایل به این کار مجاز نیست');if(!files.length)throw Error('فایل انتخاب کنید');if(files.length>10||files.some(f=>f.size>20*1048576)||files.reduce((a,f)=>a+f.size,0)>50*1048576)throw Error('حداکثر ۱۰ فایل، هر فایل ۲۰ و مجموع ۵۰ مگابایت است');const actor=me(),revision=t.revision,db=await workflowDB;const tx=db.transaction(['files','versions'],'readwrite'),done=transactionDone(tx);const meta=files.map(f=>({id:crypto.randomUUID(),name:f.name,size:f.size,type:f.type}));for(let i=0;i<files.length;i++)tx.objectStore('files').add({...meta[i],blob:files[i]});const v={id:crypto.randomUUID(),taskId:t.id,label:label.trim()||'فایل‌های کار',created:now(),by:actor,files:meta};tx.objectStore('versions').add(v);await done;if(me()!==actor||!tasks.includes(t)||t.revision!==revision||t.status==='بسته‌شده')throw Error('فایل ذخیره شد؛ کار به‌روز شده است. دوباره آن را باز کنید.');invalidateReview(t);stateLog(t,'نسخه جدید فایل‌ها ثبت شد: '+v.label);if(t.assignedBy!==actor)notifyTask(t,[t.assignedBy],'فایل تازه برای «'+t.title+'» ثبت شد.');save();return v}
